     [("Estaba cenando cuando sonaba el teléfono.", "Estaba cenando cuando sonó el teléfono.", "打断的动作用 indefinido"), ("Estuve durmiendo cuando sonó la alarma.", "Estaba durmiendo cuando sonó la alarma.", "进行中的背景用 estaba")],
     "<b>estaba + -ando / -iendo</b>（进行）+ <b>cuando + indefinido</b>（打断）。",
